// Get the Zillow API response
const zillowData = $input.first().json;
const currentDate = $('Set').item.json.current_date;

// Check if we have results
if (!zillowData.results || zillowData.results.length === 0) {
  return [{
    json: {
      error: 'No results from Zillow API',
      date: currentDate
    }
  }];
}

// Helper functions
const median = (arr) => {
  if (arr.length === 0) return 0;
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0 
    ? Math.round((sorted[mid - 1] + sorted[mid]) / 2)
    : sorted[mid];
};

const avg = (arr) => {
  if (arr.length === 0) return 0;
  return Math.round(arr.reduce((a, b) => a + b, 0) / arr.length);
};

// Extract data from properties
const properties = zillowData.results;
const prices = [];
const pricesPerSqft = [];
const daysOnMarket = [];

for (const prop of properties) {
  // Skip if missing critical data
  if (!prop.unformattedPrice || !prop.livingArea || prop.livingArea === 0) {
    continue;
  }

  prices.push(prop.unformattedPrice);
  pricesPerSqft.push(Math.round(prop.unformattedPrice / prop.livingArea));

  // Use daysOnZillow if available
  if (prop.daysOnZillow !== undefined) {
    daysOnMarket.push(prop.daysOnZillow);
  }
}

// Calculate metrics
const metrics = {
  date: currentDate,
  area: 'Seattle Capitol Hill',
  avg_price: avg(prices),
  avg_price_per_sqft: avg(pricesPerSqft),
  median_days_on_market: median(daysOnMarket),
  active_inventory: properties.length,
  total_properties_analyzed: prices.length
};

// Return the calculated metrics
return [{ json: metrics }];

// Get all historical data from Google Sheets
const allData = $input.all();

// Check if we have any data
if (allData.length === 0) {
  return [{
    json: {
      error: 'No historical data found',
      is_first_week: true
    }
  }];
}

// Get the last 2 rows (most recent data)
// If we only have 1 row, we're in the first week
const sortedData = allData.sort((a, b) => a.json.row_number - b.json.row_number);
const lastTwoRows = sortedData.slice(-2);

// Check if this is the first week (only 1 data point)
if (lastTwoRows.length === 1) {
  return [{
    json: {
      area: lastTwoRows[0].json.area,
      this_week: lastTwoRows[0].json,
      last_week: null,
      changes: null,
      trend: 'NEW - First week of tracking',
      is_first_week: true
    }
  }];
}

// We have at least 2 weeks of data - compare them
const lastWeek = lastTwoRows[0].json;
const thisWeek = lastTwoRows[1].json;

// Calculate percentage changes
const priceChange = ((thisWeek.avg_price - lastWeek.avg_price) / lastWeek.avg_price * 100).toFixed(1);
const pricePerSqftChange = ((thisWeek.avg_price_per_sqft - lastWeek.avg_price_per_sqft) / lastWeek.avg_price_per_sqft * 100).toFixed(1);
const domChange = ((thisWeek.median_days_on_market - lastWeek.median_days_on_market) / lastWeek.median_days_on_market * 100).toFixed(1);
const inventoryChange = ((thisWeek.active_inventory - lastWeek.active_inventory) / lastWeek.active_inventory * 100).toFixed(1);

// Determine market trend
let trend = 'STABLE';
if (pricePerSqftChange < -3 || domChange > 20 || inventoryChange > 15) {
  trend = 'COOLING';
} else if (pricePerSqftChange > 3 || domChange < -20 || inventoryChange < -15) {
  trend = 'HEATING';
}

// Return comparison
return [{
  json: {
    area: thisWeek.area,
    this_week: {
      date: thisWeek.date,
      avg_price: thisWeek.avg_price,
      avg_price_per_sqft: thisWeek.avg_price_per_sqft,
      median_days_on_market: thisWeek.median_days_on_market,
      active_inventory: thisWeek.active_inventory
    },
    last_week: {
      date: lastWeek.date,
      avg_price: lastWeek.avg_price,
      avg_price_per_sqft: lastWeek.avg_price_per_sqft,
      median_days_on_market: lastWeek.median_days_on_market,
      active_inventory: lastWeek.active_inventory
    },
    changes: {
      price_change_pct: parseFloat(priceChange),
      price_per_sqft_change_pct: parseFloat(pricePerSqftChange),
      dom_change_pct: parseFloat(domChange),
      inventory_change_pct: parseFloat(inventoryChange)
    },
    trend: trend,
    is_first_week: false
  }
}];

// Get the OpenAI response
const input = $input.first().json;

let reportText = '';

// Try multiple possible structures
if (typeof input === 'string') {
  // If it's already a string
  reportText = input;
} else if (input.output && Array.isArray(input.output)) {
  // Nested structure (what you got earlier)
  const content = input.output[0]?.content;
  if (Array.isArray(content)) {
    reportText = content[0]?.text || '';
  }
} else if (input.content && Array.isArray(input.content)) {
  // Another possible structure
  reportText = input.content[0]?.text || '';
} else if (input.text) {
  // Direct text field
  reportText = input.text;
} else if (input.summary) {
  // Structured output format
  reportText = input.summary;
} else if (input.message && input.message.content) {
  // Yet another possible format
  reportText = input.message.content;
}

// Fallback
if (!reportText) {
  reportText = JSON.stringify(input, null, 2);
}

// Return clean text
return [{
  json: {
    report: reportText,
    date: new Date().toISOString().split('T')[0]
  }
}];
